___CSS_LOADER_EXPORT___.push([module.id, `:host {
  display: block;
  background: #f5f1e9;
  min-height: 100vh;
}

.cms-shell {
  max-width: 1440px;
  margin: 0 auto;
  padding: 28px;
  font-family: Inter, Arial, sans-serif;
  color: #113b49;
}

.topbar {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;
  margin-bottom: 24px;
}

.topbar h1 {
  margin: 4px 0 7px;
  font-size: 34px;
}

.topbar p {
  margin: 0;
  color: #657a82;
}

.eyebrow {
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.18em;
  color: #0a6079;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 18px;
}

.unsaved {
  font-size: 12px;
  color: #b46a12;
}

.back {
  color: #0a536b;
  text-decoration: none;
  font-weight: 750;
  background: #fff;
  border: 1px solid #d8e3e6;
  padding: 10px 14px;
  border-radius: 10px;
}

.cms-layout {
  display: grid;
  grid-template-columns: 290px minmax(0, 1fr);
  gap: 22px;
}

.side-nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: sticky;
  top: 18px;
  align-self: start;
}

.side-nav button {
  display: flex;
  gap: 12px;
  text-align: left;
  border: 1px solid #dce7eb;
  background: #fff;
  border-radius: 13px;
  padding: 13px;
  cursor: pointer;
  color: #163d4b;
  transition: 0.15s;
}

.side-nav button:hover {
  transform: translateX(2px);
  border-color: #8eb6c2;
}

.side-nav button.active {
  border-color: #0a6079;
  background: #e8f4f6;
  box-shadow: 0 6px 16px rgba(10, 83, 107, 0.08);
}

.nav-icon {
  display: grid;
  place-items: center;
  flex: 0 0 32px;
  height: 32px;
  border-radius: 9px;
  background: #f0f5f6;
  font-weight: 900;
}

.side-nav strong, .side-nav small {
  display: block;
}

.side-nav small {
  margin-top: 3px;
  color: #687d85;
  line-height: 1.25;
  font-size: 11px;
}

main {
  background: #fff;
  border: 1px solid #dce7eb;
  border-radius: 18px;
  padding: 22px;
  box-shadow: 0 10px 35px rgba(12, 52, 68, 0.07);
  min-width: 0;
}

.editor-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  border-bottom: 1px solid #e8eef0;
  padding-bottom: 18px;
  margin-bottom: 18px;
}

.editor-head h2 {
  margin: 0 0 5px;
  font-size: 25px;
}

.editor-head p {
  margin: 0;
  color: #6b7f87;
}

.actions {
  display: flex;
  gap: 9px;
}

.actions button, .add, .secondary, .primary {
  border-radius: 10px;
  padding: 10px 15px;
  font-weight: 750;
  cursor: pointer;
  border: 1px solid #b9cbd2;
}

.secondary {
  background: #fff;
  color: #294d59;
}

.primary {
  background: #0a536b !important;
  color: #fff !important;
  border-color: #0a536b !important;
}

.primary:disabled {
  opacity: 0.55;
}

.notice {
  padding: 11px 13px;
  border-radius: 10px;
  margin: 12px 0;
}

.success {
  background: #e7f7ee;
  color: #17663c;
}

.error {
  background: #fff0f0;
  color: #9a2020;
}

.loading {
  padding: 60px;
  text-align: center;
}

.language-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #f2f7f8;
  border: 1px solid #dbe9ec;
  border-radius: 12px;
  padding: 11px 14px;
  margin-bottom: 18px;
}

.language-bar label {
  font-weight: 800;
}

.language-bar select {
  width: 170px;
}

.language-bar span {
  font-size: 12px;
  color: #61747c;
}

.panel {
  border: 1px solid #dde8eb;
  border-radius: 14px;
  padding: 18px;
  background: #fcfefe;
}

.panel h3, .collection-head h3 {
  margin: 0 0 4px;
}

.section-help, .collection-head p {
  margin: 0;
  color: #6b7d84;
  font-size: 13px;
}

.subheading {
  margin-top: 24px !important;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 16px;
}

.pricing-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.form-grid .wide {
  grid-column: 1/-1;
}

label span, .field-block > label > span, .repeat-card label span {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 800;
  color: #5e747d;
  margin-bottom: 6px;
}

input, textarea, select {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #cbdadd;
  border-radius: 9px;
  padding: 10px 11px;
  background: #fff;
  color: #173e4b;
  font: inherit;
}

textarea {
  resize: vertical;
  line-height: 1.45;
}

input:focus, textarea:focus, select:focus {
  outline: 2px solid rgba(10, 96, 121, 0.16);
  border-color: #0a6079;
}

.repeat-card.compact {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 12px;
  background: #fff;
  border: 1px solid #e1eaec;
  padding: 13px;
  border-radius: 11px;
  margin-top: 10px;
}

.collection-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.add {
  background: #0a6079;
  color: #fff;
  border-color: #0a6079;
}

.outing-card {
  border: 1px solid #dbe6e9;
  border-radius: 15px;
  padding: 17px;
  margin-bottom: 14px;
  background: #fff;
  box-shadow: 0 4px 13px rgba(20, 58, 70, 0.035);
}

.card-head {
  display: flex;
  justify-content: space-between;
  gap: 15px;
  align-items: center;
  border-bottom: 1px solid #edf2f3;
  padding-bottom: 12px;
}

.card-title {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
}

.order {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  background: #0a536b;
  color: #fff;
  border-radius: 50%;
  font-weight: 800;
}

.title-input {
  font-weight: 800;
  font-size: 18px;
  border-color: transparent;
  background: #f7fafb;
}

.card-tools {
  display: flex;
  align-items: center;
  gap: 6px;
}

.card-tools button {
  border: 1px solid #d3dfe2;
  background: #fff;
  border-radius: 7px;
  padding: 7px 9px;
  cursor: pointer;
}

.danger-link {
  color: #ad3030 !important;
}

.switch {
  display: inline-flex !important;
  align-items: center;
  gap: 7px;
  font-size: 12px !important;
  text-transform: none !important;
  letter-spacing: 0 !important;
  margin: 0 !important;
}

.switch input {
  display: none;
}

.switch span {
  width: 35px;
  height: 20px;
  border-radius: 20px;
  background: #c5d1d4;
  position: relative;
  margin: 0 !important;
}

.switch span:after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  background: white;
  border-radius: 50%;
  left: 2px;
  top: 2px;
  transition: 0.2s;
}

.switch input:checked + span {
  background: #22845a;
}

.switch input:checked + span:after {
  left: 17px;
}

.list-editor {
  margin-top: 15px;
  background: #f8fbfb;
  border-radius: 10px;
  padding: 12px;
}

.list-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.list-title button, .array-head button {
  border: 0;
  background: transparent;
  color: #0a6079;
  font-weight: 800;
  cursor: pointer;
}

.list-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 7px;
}

.list-row > span {
  color: #22845a;
}

.list-row button, .array-item .remove {
  border: 0;
  background: #fff0f0;
  color: #ad3030;
  border-radius: 7px;
  width: 30px;
  height: 30px;
  font-size: 20px;
}

.service-card {
  display: grid;
  grid-template-columns: 45px 1fr 120px 160px 35px;
  gap: 12px;
  align-items: end;
  border: 1px solid #dbe6e9;
  border-radius: 13px;
  padding: 14px;
  margin-bottom: 10px;
}

.service-fields {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 10px;
}

.icon-danger {
  border: 0;
  background: #fff0f0;
  color: #a72c2c;
  border-radius: 8px;
  height: 40px;
  font-size: 22px;
  cursor: pointer;
}

.visual-editor {
  padding: 20px;
}

.object-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.object-grid.nested {
  padding: 12px;
  background: #f8fbfb;
  border-radius: 10px;
}

.field-block.full, .nested-section, .array-section {
  grid-column: 1/-1;
}

.nested-section {
  border-top: 1px solid #e2eaec;
  margin-top: 8px;
  padding-top: 14px;
}

.nested-section h4, .array-head h4 {
  margin: 0;
  color: #174657;
}

.array-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.array-item {
  display: flex;
  gap: 8px;
  align-items: start;
  margin: 7px 0;
}

.array-item > .object-grid {
  flex: 1;
}

.boolean-row {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  text-transform: none !important;
  letter-spacing: 0 !important;
}

.add-field {
  margin-top: 16px;
  border: 1px dashed #8fb2bd;
  background: #f2f8f9;
  color: #0a6079;
  border-radius: 9px;
  padding: 9px 12px;
  font-weight: 700;
}

.json-editor {
  width: 100%;
  min-height: 650px;
  font: 13px/1.55 Menlo, Monaco, monospace;
  background: #102c35;
  color: #dceff3;
  border-color: #102c35;
}

.hint {
  font-size: 12px;
  color: #667b83;
}

.empty {
  padding: 45px;
  text-align: center;
  border: 1px dashed #c7d7db;
  border-radius: 12px;
  color: #73858c;
}

@media (max-width: 1050px) {
  .cms-layout {
    grid-template-columns: 240px 1fr;
  }
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .service-card {
    grid-template-columns: 40px 1fr 100px;
  }
  .service-card .category {
    grid-column: 2;
  }
  .service-card .icon-danger {
    grid-column: 3;
    grid-row: 2;
  }
  .card-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .card-tools {
    flex-wrap: wrap;
  }
}
@media (max-width: 760px) {
  .cms-shell {
    padding: 14px;
  }
  .cms-layout {
    grid-template-columns: 1fr;
  }
  .side-nav {
    position: static;
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .topbar, .editor-head, .collection-head {
    flex-direction: column;
    align-items: stretch;
  }
  .form-grid, .pricing-grid, .object-grid {
    grid-template-columns: 1fr;
  }
  .repeat-card.compact {
    grid-template-columns: 1fr 1fr;
  }
  .service-card {
    grid-template-columns: 35px 1fr;
  }
  .service-fields {
    grid-template-columns: 1fr;
  }
  .service-card .price, .service-card .category {
    grid-column: 2;
  }
  .actions {
    flex-wrap: wrap;
  }
}
.language-bar {
  justify-content: space-between;
  flex-wrap: wrap;
}

.language-picker, .translation-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.translation-actions {
  margin-left: auto;
}

.overwrite-option {
  display: flex !important;
  align-items: center;
  gap: 7px;
  font-size: 12px !important;
  text-transform: none !important;
  letter-spacing: 0 !important;
  margin: 0 !important;
}

.overwrite-option input {
  width: auto;
}

.translate-button {
  border: 1px solid #0a6079;
  background: #e6f4f7;
  color: #0a536b;
  border-radius: 10px;
  padding: 10px 14px;
  font-weight: 800;
  cursor: pointer;
}

.translate-button:disabled {
  opacity: 0.6;
  cursor: default;
}

@media (max-width: 760px) {
  .language-picker, .translation-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .translation-actions {
    margin-left: 0;
  }
  .translate-button {
    width: 100%;
  }
